mapper.select:
SELECT child.*, child.locked_by AS lock_owner, child.created_by AS creator, child.last_modified_by AS modifier, submission.submitted_on AS submitted_on, submission.submitter AS submitter, COUNT(
CASE WHEN grand_child.system_type IN
#{type}
THEN 1 ELSE NULL END
grand_child.id
) as children_count FROM item child LEFT JOIN item parent ON child.parent_id = parent.id LEFT JOIN item grand_child ON grand_child.parent_id = child.id LEFT OUTER JOIN ( SELECT ipi1.item_id as item_id, pp1.submitter_id AS submitter, pp1.submitted_on AS submitted_on FROM item_publish_item ipi1 INNER JOIN publish_item pi1 ON ipi1.publish_item_id = pi1.id INNER JOIN publish_package pp1 ON pi1.package_id = pp1.id WHERE (pp1.package_state & #{packageState}) > 0 AND pp1.approval_state IN
#{approvalState}
ORDER BY pp1.submitted_on DESC LIMIT 0, 1 ) as submission ON submission.item_id = child.id WHERE parent.site_id = #{siteId} AND (parent.path = #{path} OR parent.path = CONCAT(#{path}, '/index.xml')) AND (parent.system_type != #{systemTypeFolder} OR NOT EXISTS(SELECT * FROM item page WHERE page.site_id = parent.site_id AND page.system_type = 'page' AND page.path = CONCAT(parent.path, '/index.xml'))) AND child.ignored = 0 AND (child.system_type != #{systemTypeFolder} OR NOT EXISTS (select * from item page where page.site_id = child.site_id and page.path = concat(child.path, '/index.xml')))
AND (grand_child.ignored = 0 OR grand_child.ignored IS NULL) AND (grand_child.system_type != #{systemTypeFolder} OR NOT EXISTS (select * from item page where page.site_id = grand_child.site_id and page.path = concat(grand_child.path, '/index.xml'))) GROUP BY child.id, child.label, child.path, child.system_type
ORDER BY child.label ${order}, child.path ${order}
ORDER BY IF(FIELD(child.system_type, 'folder')=0,1,0), FIELD(child.system_type, 'folder'), child.label ${order}, child.path ${order}
ORDER BY child.last_modified_on ${order}, child.label ${order}, child.path ${order}
ORDER BY child.label ${order}, child.path ${order}
LIMIT #{offset},#{limit}

SELECT i.*
FROM item i
WHERE i.site_id = #{siteId}
AND i.path IN

		#{path}
		, CONCAT(#{path}, '/index.xml')

AND i.ignored = 0


	AND (
			i.system_type != #{systemTypeFolder}
		OR
			NOT EXISTS(SELECT *
						FROM item page
						WHERE page.site_id = i.site_id
						AND page.system_type = #{systemTypePage}
						AND page.path = CONCAT(item.path, '/index.xml')
			)
	)


WHERE i.site_id = #{siteId}

AND (i.state & #{statesBitMap}) > 0
AND i.system_type <> #{systemTypeFolder}

GROUP BY i.id

LIMIT #{offset}, #{limit}


WHERE s1.id = #{siteId}
AND i.path IN

		#{path}
		, CONCAT(#{path}, '/index.xml')


GROUP BY i.id


WHERE s1.id = #{siteId}
AND i.path = #{path}

GROUP BY i.id
LIMIT 0, 1

(

	WHERE s1.id = #{siteId}
	AND i.ignored = 0

	AND i.path = CONCAT(TRIM(TRAILING '/' FROM #{path}), '/index.xml')

	GROUP BY i.id
)
UNION
(

	WHERE s1.id = #{siteId}
	AND i.path = #{path}
	AND i.ignored = 0

	GROUP BY i.id
	)
LIMIT 0, 1

